for number,route,text,evidence,reason in observations:
    old=original[number-1]
    status='不通过' if number==28 else old['执行状态']
    value=f'2026-10-14复核｜本地dev/Mock｜{route}\n{text}\n证据：'+ '、'.join(evidence.split())+'。截图、DOM及量测见配套复核证据.html。'
    edits.append({'sheet':'通用模板UI与交互用例','cell':f'I{number+1}','value':value})
    if status!=old['执行状态']:
        edits.append({'sheet':'通用模板UI与交互用例','cell':f'H{number+1}','value':status})
    cases.append({'id':old['id'],'row':number+1,'name':old['用例名称'],'oldStatus':old['执行状态'],'status':status,'route':route,'result':value,'evidence':evidence.split(),'reason':reason,'originalResult':old['实际结果/证据']})

